    {
      "section": "verifier",
      "quote": "error[E0308]: arguments to this method are incorrect\n   --> src/network/tests.rs:321:15\n    |\n321 |     icmp_repr.emit(\n    |               ^^^^\n322 |         &src_addr,\n    |         --------- expected `&IpAddress`, found `&Ipv6Address`\n323 |         &dst_addr,\n    |         --------- expected `&IpAddress`, found `&Ipv6Address`"
    },
    {
      "section": "reference_patch",
      "quote": "diff --git a/Cargo.toml b/Cargo.toml\n--- a/Cargo.toml\n+++ b/Cargo.toml\n@@ -34,25 +34,25 @@ log = \"0.4.18\"\n once_cell = \"1\"\n pretty-hex = \"0.4.1\"\n rand_core = { version = \"0.6.4\", features = [\"getrandom\"] }\n-smoltcp = \"0.10\"\n+smoltcp = \"0.11\""
    },
